"""Append supported settings from CI env without shell interpolation."""
import os
from pathlib import Path
KEYS=('CHECKOUT_COD_ENABLED','CHECKOUT_ORDER_EXPORT_ENABLED','CHECKOUT_TEST_EXPORT_ENABLED','PANCAKE_ORDER_SYNC_ENABLED','PANCAKE_GHN_DISPATCH_ENABLED','PANCAKE_PAYMENT_MAPPING_VERIFIED','COMMERCE_ENVIRONMENT', 'CHECKOUT_CARRIER_ENABLED','SMART_SHIPPING_ENABLED','SMART_SHIPPING_POLICY','GHN_TOKEN','GHN_SHOP_ID','GHN_FROM_DISTRICT_ID','GHN_FROM_WARD_CODE','GHN_ENVIRONMENT','PANCAKE_GHN_ACCOUNT_ID','CARRIER_REGISTRY_JSON','CARRIER_SECRETS_JSON','PANCAKE_API_KEY','PANCAKE_SHOP_ID','PANCAKE_WAREHOUSE_ID','PANCAKE_CATALOG_SOURCE','PANCAKE_STOCK_ONLY','PANCAKE_SYNC_ENABLED','ACP_ENABLED','ACP_ACCESS_VERIFIED','ACP_API_TOKEN','TECHCOMBANK_ACCOUNT_NUMBER','TECHCOMBANK_ACCOUNT_NAME','CHECKOUT_QR_ENABLED','CHECKOUT_PAYMENTS_PAUSED','MARKETING_ENABLED','MARKETING_SEND_ENABLED','MARKETING_POLICY_VERSION','MARKETING_FROM_EMAIL','MARKETING_CONTACT_ADDRESS','MARKETING_WELCOME_DISCOUNT_CODE','MARKETING_MAILGUN_DOMAIN','MARKETING_MAILGUN_BASE_URL','MAILGUN_WEBHOOK_SIGNING_KEY','MARKETING_AI_ENABLED','MARKETING_AI_MODEL','MARKETING_OPENAI_API_KEY','STORE_PUBLIC_API_URL','FEEDS_ENABLED','SHOPPING_AI_ENABLED','SHOPPING_AI_MODEL','SHOPPING_OPENAI_API_KEY')
KEYS += ('POD_ENABLED','POD_SUBMIT_ENABLED','POD_ACCOUNT_AUTOMATION_VERIFIED','POD_NEW_PIPELINE_ENABLED','POD_PRINTIFY_MEDIA_WRITE_ENABLED','POD_PRINTIFY_PRODUCT_WRITE_ENABLED','POD_ORDER_CREATE_ENABLED','POD_PRODUCTION_RELEASE_ENABLED','POD_WEBHOOK_ENABLED','PRINTIFY_SHOP_ID','PRINTIFY_API_TOKEN','PRINTIFY_WEBHOOK_SECRET','PRINTIFY_WEBHOOK_PREVIOUS_SECRET','POD_R2_BUCKET_NAME')

def append_settings(target,environ):
    values=[]
    for key in KEYS:
        value=environ.get(key,'')
        if not value:continue
        if any(c in value for c in ('\n','\r','\x00')):raise ValueError('Commerce setting must be a single line: '+key)
        if (key.endswith('_ENABLED') or key.endswith('_PAUSED') or key in ('ACP_ACCESS_VERIFIED','PANCAKE_STOCK_ONLY')) and value not in ('true','false'):raise ValueError('Feature flag must be true or false: '+key)
        values.append(key+'='+value)
    with Path(target).open('a',encoding='utf-8') as output:output.write('\n'+'\n'.join(values)+'\n')
    return len(values)
if __name__=='__main__':print('Supported commerce settings appended:',append_settings('.env',os.environ))
